/// <summary>
/// Display is pricing attributes are enabled for this journal
/// </summary>
/// <returns>True if pricing attributes are enabled for this journal; Otherwise false</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPriceDiscPriceAttributeEnable priceDiscPriceAttributeEnable()
{
    return PriceDiscAdmName::find(this.JournalName).PriceDiscPriceAttributeEnable;
}
